contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depositAmount, uint cashOutAmount) public payable {
        require(depositAmount > c.MinDeposit(), "deposit too small");
        require(address(this).balance >= depositAmount, "not enough balance");

        // Capture before-values through public surface.
        uint balBefore = c.balances(address(this));
        uint cEthBefore = address(c).balance;

        // Setup: deposit so the caller has a positive balance.
        c.Deposit{value: depositAmount}();

        // Read post-deposit values.
        uint balAfterDeposit = c.balances(address(this));
        uint cEthAfterDeposit = address(c).balance;

        // Precondition for the deciding call: amount is payable from caller's balance.
        require(cashOutAmount <= balAfterDeposit, "cashOut exceeds balance");

        // Deciding call: capture whether it reverts.
        bool reverted;
        try c.CashOut(cashOutAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule over all inputs:
        // (1) CashOut does not revert for a payable amount.
        // (2) CashOut reduces c's ETH balance by exactly the amount.
        // (3) CashOut reduces the caller's c-balance by exactly the amount.
        assert(
            !reverted &&
            address(c).balance == cEthAfterDeposit - cashOutAmount &&
            c.balances(address(this)) == balAfterDeposit - cashOutAmount &&
            balAfterDeposit == balBefore + depositAmount &&
            cEthAfterDeposit == cEthBefore + depositAmount
        );
    }

    receive() external payable {}
}

